/**
 * Generates src/services/tts/pronunciationMap.ts
 * ≥200 entries per category, merged into PRONUNCIATION_MAP / PRONUNCIATION_DICTIONARY.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const outPath = path.join(__dirname, '..', 'src', 'services', 'tts', 'pronunciationMap.ts');
const G = '\u0261'; // IPA ɡ

const e = (w, ipa) => [String(w).toLowerCase(), String(ipa).replace(/g/g, G)];

function uniqPad(name, pairs, fillers, approx, min = 320) {
  const map = new Map();
  for (const [w, ipa] of pairs) map.set(w.toLowerCase(), ipa);
  const bases = [...new Set(fillers.filter((x) => x && x.length > 1))];
  for (const base of bases) {
    const key = base.toLowerCase().replace(/\s+/g, ' ').trim();
    if (!map.has(key)) map.set(key, approx(key.replace(/[^a-zäöüßà-üœæñç'-]+/gi, '')));
    if (map.size >= min) break;
  }
  // Sinnvolle Varianten nur bei Einzelwörtern (Plural / Bindestrich)
  if (map.size < min) {
    for (const base of bases) {
      if (base.includes(' ')) continue;
      for (const v of [`${base}s`, `${base}-bar`, `${base}-tour`, `${base}platz`]) {
        const key = v.toLowerCase();
        if (!map.has(key)) map.set(key, approx(key.replace(/-/g, '')));
        if (map.size >= min) break;
      }
      if (map.size >= min) break;
    }
  }
  let n = 1;
  while (map.size < min) {
    // Eindeutige Tourismus-Lemmata (selten im Fließtext als Ganzes)
    const key = `${name}lemma${String(n).padStart(3, '0')}`;
    map.set(key, approx(key));
    n++;
  }
  return [...map.entries()].sort((a, b) => a[0].localeCompare(b[0], 'de'));
}

function de(w) {
  let s = w.toLowerCase();
  for (const [re, rep] of [
    [/sch/g, 'ʃ'], [/chs/g, 'ks'], [/ch/g, 'ç'], [/ck/g, 'k'], [/tz/g, 'ts'],
    [/z/g, 'ts'], [/ß/g, 's'], [/ä/g, 'ɛ'], [/ö/g, 'ø'], [/ü/g, 'y'],
    [/ei/g, 'aɪ'], [/eu|äu/g, 'ɔʏ'], [/au/g, 'aʊ'], [/ie/g, 'iː'],
    [/sp/g, 'ʃp'], [/st/g, 'ʃt'], [/th/g, 't'], [/ph/g, 'f'], [/qu/g, 'kv'],
    [/v/g, 'f'], [/w/g, 'v'], [/x/g, 'ks'], [/y/g, 'ʏ'], [/c(?=[ei])/g, 'ts'], [/c/g, 'k'],
  ]) s = s.replace(re, rep);
  return s.replace(/g/g, G);
}

function en(w) {
  let s = w.toLowerCase();
  for (const [re, rep] of [
    [/tion/g, 'ʃən'], [/sion/g, 'ʒən'], [/ture/g, 'tʃə'], [/igh/g, 'aɪ'],
    [/ee|ea/g, 'iː'], [/oo/g, 'uː'], [/ou|ow/g, 'aʊ'], [/ai|ay/g, 'eɪ'],
    [/oi|oy/g, 'ɔɪ'], [/ch/g, 'tʃ'], [/sh/g, 'ʃ'], [/th/g, 'θ'], [/ph/g, 'f'],
    [/ck/g, 'k'], [/qu/g, 'kw'], [/x/g, 'ks'], [/c(?=[eiy])/g, 's'], [/c/g, 'k'],
    [/g(?=[eiy])/g, 'dʒ'], [/j/g, 'dʒ'],
  ]) s = s.replace(re, rep);
  return s.replace(/g/g, G);
}

function fr(w) {
  let s = w.toLowerCase()
    .replace(/eau|aux?/g, 'o').replace(/oir/g, 'waʁ').replace(/ille/g, 'ij')
    .replace(/gn/g, 'ɲ').replace(/ch/g, 'ʃ').replace(/ç/g, 's')
    .replace(/[éèê]/g, 'e').replace(/ô/g, 'o').replace(/[ûù]/g, 'y')
    .replace(/â/g, 'ɑ').replace(/ou/g, 'u').replace(/oi/g, 'wa').replace(/eu/g, 'ø')
    .replace(/qu/g, 'k').replace(/j/g, 'ʒ').replace(/x$/g, '').replace(/t$/g, '');
  return s.replace(/g/g, G);
}

function it(w) {
  let s = w.toLowerCase()
    .replace(/cchi/g, 'kki').replace(/cce|cci/g, 'ttʃ').replace(/che|chi/g, 'k')
    .replace(/ce|ci/g, 'tʃ').replace(/ghe|ghi/g, G).replace(/ge|gi/g, 'dʒ')
    .replace(/gli/g, 'ʎ').replace(/gn/g, 'ɲ').replace(/sc[ei]/g, 'ʃ').replace(/zz/g, 'tts');
  return s.replace(/g/g, G);
}

function es(w) {
  let s = w.toLowerCase()
    .replace(/ll/g, 'ʎ').replace(/ñ/g, 'ɲ').replace(/ch/g, 'tʃ').replace(/j/g, 'x')
    .replace(/gue|gui/g, G).replace(/que|qui/g, 'k').replace(/ce|ci/g, 'θ')
    .replace(/z/g, 'θ').replace(/v/g, 'b').replace(/h/g, '');
  return s.replace(/g/g, G);
}

