function fmtEntries(entries) {
  return entries
    .map(([k, v]) => `  ${JSON.stringify(k)}: ${JSON.stringify(v)},`)
    .join('\n');
}

function catBlock(exportName, comment, entries) {
  return `/** ${comment} (${entries.length} Einträge) */\nexport const ${exportName}: Record<string, string> = {\n${fmtEntries(entries)}\n};\n`;
}

